"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["4619"],{14059(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.banca.votacao_do_recurso_incompleta","status":422,"titulo":"A vota\xe7\xe3o do recurso est\xe1 incompleta"},"descricao":{"codigo":"uniplus.selecao.banca.votacao_do_recurso_incompleta","requisitos":["UNI-REQ-0275","UNI-REQ-0338","UNI-REQ-0384"],"oQueAconteceu":["A banca declarada por ato individual (`ATO_INDIVIDUAL`) traz alguns, mas n\xe3o\\ntodos, os campos da vota\xe7\xe3o usada no julgamento do recurso: qu\xf3rum, crit\xe9rio de\\ndecis\xe3o e forma de encerramento.","No ato individual, qualquer pessoa titular designada pratica o ato sem qu\xf3rum nem\\nvota\xe7\xe3o (UNI-REQ-0338). Ao julgar recurso, por\xe9m, a banca delibera com voto e\\nqu\xf3rum (UNI-REQ-0384), e por isso a configura\xe7\xe3o pode trazer, ao lado do ato\\nindividual, a vota\xe7\xe3o do recurso (UNI-REQ-0275). Essa vota\xe7\xe3o vale s\xf3 para o\\njulgamento do recurso. As op\xe7\xf5es aceitas s\xe3o:","- **nenhum campo de vota\xe7\xe3o:** a banca s\xf3 pratica o ato individual;\\n- **qu\xf3rum, crit\xe9rio e encerramento juntos:** a vota\xe7\xe3o do recurso est\xe1 completa.","Declarar s\xf3 parte deles \xe9 recusado, porque o recurso ficaria sem regra para\\ndecidir. A recusa traz uma entrada por campo que falta, na lista `errors[]`, no\\ncaminho do campo, por exemplo `fases[0].bancasRequeridas[0].regraDeDeliberacao.quorum`\\nna banca da fase e `etapas[0].bancas[0].regraDeDeliberacao.quorum` na banca da etapa.\\nAs confer\xeancias finas de cada campo (qu\xf3rum no intervalo, desempate, resultado\\nsem unanimidade) continuam com recusa pr\xf3pria.","A publica\xe7\xe3o exige a vota\xe7\xe3o completa da banca por ato individual que julga\\nrecurso: a banca de an\xe1lise de recursos e a banca avaliadora que julga o recurso\\npor n\xe3o haver dedicada no lugar. A falta, nesse caso, \xe9 a recusa de\\n[regra de delibera\xe7\xe3o obrigat\xf3ria](/erros/uniplus.selecao.banca.regra_de_deliberacao_obrigatoria)."],"comoResolver":["Declare os tr\xeas campos da vota\xe7\xe3o do recurso, ou retire todos. Para os campos,\\nver [crit\xe9rio](/erros/uniplus.selecao.banca.criterio_obrigatorio),\\n[encerramento](/erros/uniplus.selecao.banca.encerramento_obrigatorio) e\\n[qu\xf3rum](/erros/uniplus.selecao.banca.quorum_fora_do_intervalo). Se o edital manda\\na banca votar em todas as decis\xf5es, mude o modo para `COLEGIADA_COM_VOTACAO`; ver\\n[modo de delibera\xe7\xe3o inv\xe1lido](/erros/uniplus.selecao.banca.modo_de_deliberacao_invalido)."],"ondeAparece":["- Defini\xe7\xe3o do cronograma de fases do processo seletivo\\n- Defini\xe7\xe3o de etapas do processo seletivo\\n- Leitura do documento de configura\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Banca"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);